donut.source:
// Parts of a whole as a donut (or a pie with hole 0): each slice in its own style colour,
// named outside on a short leader with its share, and the total or a headline in the
// middle. For budgets, compositions and survey answers.
const d = api.data,
  t = api.theme;
const W = api.width,
  H = api.height;
const esc = (s) =>
  String(s ?? "").replace(
    /[&<>"]/g,
    (ch) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[ch],
  );
const font = t.font || "system-ui";
const ctx = document.createElement("canvas").getContext("2d");
const measure = (s, size, weight = 400) => {
  ctx.font = `${weight} ${size}px ${font}`;
  return ctx.measureText(String(s ?? "")).width;
};
const ink = t.ink || "#222",
  paper = t.paper || "#fff",
  muted = t.muted || "#888",
  accent = t.accent || "#d97757",
  accent2 = t.accent2 || "#4f7c8a";
const sw = Math.max(1, Number(t.stroke ?? 1.6) * 0.85);
const size = Number(d.size ?? 14);
const hex = (c) => {
  const m = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(String(c ?? "").trim());
  if (!m) return null;
  const h = m[1].length === 3 ? [...m[1]].map((x) => x + x).join("") : m[1];
  return [0, 2, 4].map((i) => parseInt(h.slice(i, i + 2), 16));
};
const mix = (a, b, k) => {
  const p = hex(a),
    q = hex(b);
  if (!p || !q) return k < 0.5 ? a : b;
  return (
    "#" +
    p
      .map((v, i) =>
        Math.round(v + (q[i] - v) * k)
          .toString(16)
          .padStart(2, "0"),
      )
      .join("")
  );
};
// Distinct colours from the style: accent, accent2, then blends of them with ink.
const palette = (n) =>
  Array.from(
    { length: n },
    (_, i) =>
      [
        accent,
        accent2,
        mix(accent, ink, 0.45),
        mix(accent2, ink, 0.45),
        mix(accent, accent2, 0.5),
        muted,
      ][i % 6],
  );
const items = (d.items || []).map((it) =>
  Array.isArray(it) ? { label: it[0], value: it[1] } : it,
);
const total =
  items.reduce((s, i) => s + Math.max(0, Number(i.value) || 0), 0) || 1;
const colors = palette(items.length);
const labelled = d.labels !== false;
const R = Math.min(
  W / 2 - (labelled ? size * 7 : sw),
  H / 2 - (labelled ? size * 1.8 : sw),
);
const hole = Math.min(0.9, Math.max(0, Number(d.hole ?? 0.58)));
const cx = W / 2,
  cy = H / 2;
const pt = (a, r) => ({ x: cx + r * Math.cos(a), y: cy + r * Math.sin(a) });
let out = "",
  a0 = -Math.PI / 2;
items.forEach((it, i) => {
  const share = Math.max(0, Number(it.value) || 0) / total;
  if (!share) return;
  const a1 = a0 + share * Math.PI * 2;
  const big = a1 - a0 > Math.PI ? 1 : 0;
  const c = it.color || colors[i];
  if (share >= 0.9999)
    out += `<circle cx="${cx}" cy="${cy}" r="${(R * (1 + hole)) / 2}" fill="none" stroke="${c}" stroke-width="${R * (1 - hole) || R}"/>`;
  else {
    const p0 = pt(a0, R),
      p1 = pt(a1, R),
      q1 = pt(a1, R * hole),
      q0 = pt(a0, R * hole);
    out += `<path d="M${p0.x} ${p0.y}A${R} ${R} 0 ${big} 1 ${p1.x} ${p1.y}${hole ? `L${q1.x} ${q1.y}A${R * hole} ${R * hole} 0 ${big} 0 ${q0.x} ${q0.y}` : `L${cx} ${cy}`}Z" fill="${c}" stroke="${paper}" stroke-width="2" stroke-linejoin="round"/>`;
  }
  if (labelled) {
    const am = (a0 + a1) / 2,
      right = Math.cos(am) >= 0;
    const e = pt(am, R + 4),
      k = pt(am, R + size * 1.2);
    const tx = k.x + (right ? size * 0.9 : -size * 0.9);
    out += `<path class="plain" d="M${e.x} ${e.y}L${k.x} ${k.y}H${tx + (right ? -size * 0.3 : size * 0.3)}" fill="none" stroke="${muted}" stroke-width="1"/>`;
    out += `<text x="${tx}" y="${k.y - size * 0.45}" text-anchor="${right ? "start" : "end"}" font-size="${size}" font-weight="600" fill="${ink}">${esc(it.label)}</text>`;
    out += `<text x="${tx}" y="${k.y + size * 0.65}" text-anchor="${right ? "start" : "end"}" font-size="${size * 0.82}" fill="${muted}">${esc(it.note ?? Math.round(share * 100) + "%")}</text>`;
  }
  a0 = a1;
});
if (hole && d.center)
  out += `<text x="${cx}" y="${cy - (d.centerNote ? size * 0.55 : 0)}" text-anchor="middle" font-size="${Math.min(size * 1.9, ((R * hole * 1.4) / Math.max(1, String(d.center).length)) * 1.6)}" font-weight="700" fill="${ink}">${esc(d.center)}</text>`;
if (hole && d.centerNote)
  out += `<text x="${cx}" y="${cy + size * 1.15}" text-anchor="middle" font-size="${size * 0.82}" fill="${muted}">${esc(d.centerNote)}</text>`;
const svg = api.svg(
  `<svg viewBox="0 0 ${W} ${H}" width="${W}" height="${H}" style="overflow:visible" font-family="${esc(font)}" dominant-baseline="central">${out}</svg>`,
);
// The style's texture on the shapes, never on the words.
if (d.effect) {
  const fx = api.effect(d.effect);
  for (const el of svg.querySelectorAll(
    "path:not(.plain),rect:not(.plain),circle:not(.plain)",
  ))
    el.setAttribute("filter", fx);
}
return svg;

stat.source:
// A key figure: one large number with what it counts, an optional change marked up or
// down, and a note. For headline numbers beside a diagram or a row of them as a summary.
const d = api.data,
  t = api.theme;
const W = api.width,
  H = api.height;
const esc = (s) =>
  String(s ?? "").replace(
    /[&<>"]/g,
    (ch) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[ch],
  );
const font = t.font || "system-ui";
const ctx = document.createElement("canvas").getContext("2d");
const measure = (s, size, weight = 400) => {
  ctx.font = `${weight} ${size}px ${font}`;
  return ctx.measureText(String(s ?? "")).width;
};
const ink = t.ink || "#222",
  paper = t.paper || "#fff",
  muted = t.muted || "#888",
  accent = t.accent || "#d97757",
  accent2 = t.accent2 || "#4f7c8a";
const sw = Math.max(1, Number(t.stroke ?? 1.6) * 0.85);
const size = Number(d.size ?? 14);
const color = d.color || ink;
const vs = Math.min(
  H * 0.5,
  (W * 0.92 * size * 3) / Math.max(1, measure(d.value, size * 3, 700)),
);
const valueSize = Math.min(Number(d.valueSize) || size * 3, vs);
const left = d.align === "left";
const x = left ? 0 : W / 2,
  anchor = left ? "start" : "middle";
let y = valueSize * 0.6;
let out = `<text x="${x}" y="${y}" text-anchor="${anchor}" font-size="${valueSize}" font-weight="700" fill="${color}">${esc(d.value)}${d.unit ? `<tspan font-size="${valueSize * 0.42}" font-weight="600" fill="${muted}" dx="4">${esc(d.unit)}</tspan>` : ""}</text>`;
y += valueSize * 0.55 + size * 0.9;
if (d.label) {
  out += `<text x="${x}" y="${y}" text-anchor="${anchor}" font-size="${size * 1.05}" font-weight="600" fill="${ink}">${esc(d.label)}</text>`;
  y += size * 1.5;
}
if (d.delta) {
  const up =
    (d.trend ?? (String(d.delta).trim().startsWith("-") ? "down" : "up")) ===
    "up";
  const good = d.good === "down" ? !up : up;
  const c = good ? accent2 : accent;
  const tw = measure(d.delta, size * 0.9, 600) + size * 1.4;
  const x0 = left ? 0 : W / 2 - tw / 2;
  const ay = y,
    ax = x0 + size * 0.45;
  out += `<path d="${up ? `M${ax - size * 0.32} ${ay + size * 0.2}L${ax} ${ay - size * 0.25}L${ax + size * 0.32} ${ay + size * 0.2}Z` : `M${ax - size * 0.32} ${ay - size * 0.2}L${ax} ${ay + size * 0.25}L${ax + size * 0.32} ${ay - size * 0.2}Z`}" fill="${c}"/>`;
  out += `<text x="${x0 + size * 1.1}" y="${ay}" font-size="${size * 0.9}" font-weight="600" fill="${c}">${esc(d.delta)}</text>`;
  y += size * 1.4;
}
if (d.note)
  out += `<text x="${x}" y="${y}" text-anchor="${anchor}" font-size="${size * 0.82}" fill="${muted}">${esc(d.note)}</text>`;
const svg = api.svg(
  `<svg viewBox="0 0 ${W} ${H}" width="${W}" height="${H}" style="overflow:visible" font-family="${esc(font)}" dominant-baseline="central">${out}</svg>`,
);
// The style's texture on the shapes, never on the words.
if (d.effect) {
  const fx = api.effect(d.effect);
  for (const el of svg.querySelectorAll(
    "path:not(.plain),rect:not(.plain),circle:not(.plain)",
  ))
    el.setAttribute("filter", fx);
}
return svg;

bars.source:
// A bar chart for comparing a few quantities: rounded bars on a baseline, each value
// written at its end and each name at its foot, without a grid. An accented bar stands
// out; the rest share one colour. Upright or lying.
const d = api.data,
  t = api.theme;
const W = api.width,
  H = api.height;
const esc = (s) =>
  String(s ?? "").replace(
    /[&<>"]/g,
    (ch) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[ch],
  );
const font = t.font || "system-ui";
const ctx = document.createElement("canvas").getContext("2d");
const measure = (s, size, weight = 400) => {
  ctx.font = `${weight} ${size}px ${font}`;
  return ctx.measureText(String(s ?? "")).width;
};
const ink = t.ink || "#222",
  paper = t.paper || "#fff",
  muted = t.muted || "#888",
  accent = t.accent || "#d97757",
  accent2 = t.accent2 || "#4f7c8a";
const sw = Math.max(1, Number(t.stroke ?? 1.6) * 0.85);
const size = Number(d.size ?? 14);
const hex = (c) => {
  const m = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(String(c ?? "").trim());
  if (!m) return null;
  const h = m[1].length === 3 ? [...m[1]].map((x) => x + x).join("") : m[1];
  return [0, 2, 4].map((i) => parseInt(h.slice(i, i + 2), 16));
};
const mix = (a, b, k) => {
  const p = hex(a),
    q = hex(b);
  if (!p || !q) return k < 0.5 ? a : b;
  return (
    "#" +
    p
      .map((v, i) =>
        Math.round(v + (q[i] - v) * k)
          .toString(16)
          .padStart(2, "0"),
      )
      .join("")
  );
};
// Distinct colours from the style: accent, accent2, then blends of them with ink.
const palette = (n) =>
  Array.from(
    { length: n },
    (_, i) =>
      [
        accent,
        accent2,
        mix(accent, ink, 0.45),
        mix(accent2, ink, 0.45),
        mix(accent, accent2, 0.5),
        muted,
      ][i % 6],
  );
const items = (d.items || []).map((it) =>
  Array.isArray(it) ? { label: it[0], value: it[1] } : it,
);
const n = Math.max(1, items.length);
const max = Number(
  d.max ?? Math.max(...items.map((i) => Number(i.value) || 0), 1),
);
const unit = d.unit ?? "";
const base = d.color || accent2;
const fmt = (v) => `${v}${unit}`;
const lying = d.orientation === "horizontal";
let out = "";
if (lying) {
  const lw = Math.min(
    W * 0.3,
    Math.max(...items.map((i) => measure(i.label, size)), size * 2) + size,
  );
  const vw =
    Math.max(...items.map((i) => measure(fmt(i.value), size * 0.9, 600))) +
    size;
  const slot = H / n,
    bh = Math.min(slot * 0.62, size * 2.4);
  out += `<path d="M${lw} 0V${H}" stroke="${ink}" stroke-width="${sw}"/>`;
  items.forEach((it, i) => {
    const y = slot * (i + 0.5),
      w = Math.max(0, ((W - lw - vw) * Number(it.value)) / max);
    const c = it.color || (it.accent ? accent : base);
    out += `<text x="${lw - size * 0.6}" y="${y}" text-anchor="end" font-size="${size}" fill="${ink}">${esc(it.label)}</text>`;
    out += `<path d="M${lw} ${y - bh / 2}H${lw + w - Math.min(6, w)}q${Math.min(6, w)} 0 ${Math.min(6, w)} ${Math.min(6, w)}V${y + bh / 2 - Math.min(6, w)}q0 ${Math.min(6, w)} ${-Math.min(6, w)} ${Math.min(6, w)}H${lw}Z" fill="${c}"/>`;
    out += `<text x="${lw + w + size * 0.5}" y="${y}" font-size="${size * 0.9}" font-weight="600" fill="${it.accent ? accent : ink}">${esc(fmt(it.value))}</text>`;
  });
} else {
  const top = size * 1.8,
    bottom = H - size * 2.2;
  const slot = W / n,
    bw = Math.min(slot * 0.58, size * 5);
  items.forEach((it, i) => {
    const x = slot * (i + 0.5),
      h = Math.max(0, ((bottom - top) * Number(it.value)) / max);
    const c = it.color || (it.accent ? accent : base);
    const rr = Math.min(6, h, bw / 2);
    out += `<path d="M${x - bw / 2} ${bottom}V${bottom - h + rr}q0 ${-rr} ${rr} ${-rr}H${x + bw / 2 - rr}q${rr} 0 ${rr} ${rr}V${bottom}Z" fill="${c}"/>`;
    out += `<text x="${x}" y="${bottom - h - size * 0.8}" text-anchor="middle" font-size="${size * 0.9}" font-weight="600" fill="${it.accent ? accent : ink}">${esc(fmt(it.value))}</text>`;
    out += `<text x="${x}" y="${bottom + size * 1.1}" text-anchor="middle" font-size="${size}" fill="${ink}">${esc(it.label)}</text>`;
  });
  out += `<path d="M0 ${bottom}H${W}" stroke="${ink}" stroke-width="${sw}"/>`;
}
const svg = api.svg(
  `<svg viewBox="0 0 ${W} ${H}" width="${W}" height="${H}" style="overflow:visible" font-family="${esc(font)}" dominant-baseline="central">${out}</svg>`,
);
// The style's texture on the shapes, never on the words.
if (d.effect) {
  const fx = api.effect(d.effect);
  for (const el of svg.querySelectorAll(
    "path:not(.plain),rect:not(.plain),circle:not(.plain)",
  ))
    el.setAttribute("filter", fx);
}
return svg;

label.source:
// A short label in the work's type with a paper-coloured halo, so it stays legible over
// pictures and lines. Lines break at "\n"; an optional note sits underneath, smaller.
const d = api.data,
  t = api.theme;
const W = api.width,
  H = api.height;
const size = Number(d.size ?? 16);
const align = d.align ?? "center";
const x = align === "start" ? 0 : align === "end" ? W : W / 2;
const anchor = align === "center" ? "middle" : align;
const esc = (s) =>
  String(s).replace(
    /[&<>"]/g,
    (ch) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[ch],
  );
const lines = String(d.text ?? "").split("\n");
const note = d.note ? String(d.note).split("\n") : [];
const noteSize = size * 0.78;
const total = lines.length * size * 1.25 + note.length * noteSize * 1.3;
let y = (H - total) / 2 + size * 0.95;
const halo =
  d.halo === false
    ? ""
    : `paint-order="stroke" stroke="${t.paper || "#fff"}" stroke-width="${Math.max(3, size / 4)}" stroke-linejoin="round"`;
const rows = [];
for (const line of lines) {
  rows.push(
    `<text x="${x}" y="${y}" text-anchor="${anchor}" font-size="${size}" font-weight="${d.weight ?? 500}" fill="${d.color || t.ink || "#222"}" ${halo}>${esc(line)}</text>`,
  );
  y += size * 1.25;
}
for (const line of note) {
  rows.push(
    `<text x="${x}" y="${y}" text-anchor="${anchor}" font-size="${noteSize}" fill="${d.noteColor || t.muted || "#777"}" ${halo}>${esc(line)}</text>`,
  );
  y += noteSize * 1.3;
}
return api.svg(
  `<svg viewBox="0 0 ${W} ${H}" width="${W}" height="${H}" style="overflow:visible" font-family="${esc(t.font || "system-ui")}">${rows.join("")}</svg>`,
);

arrow.source:
// An arrow with a head sized to its line, between api.from and api.to (as a link) or
// between data.from and data.to (normalized points of the module). It runs as a curve
// (straight unless bent), or at right angles as flowcharts do: elbow leaves and arrives
// along the sides its ends meet, corner turns once; both step straight out of a module
// before turning and go round when the ends face away.
const d = api.data,
  t = api.theme;
const W = api.width,
  H = api.height;
const w = Number(d.width ?? t.stroke ?? 1.6);
const color = d.color || t.ink || "#333";
const at = (p, fallback) => (p ? { x: p.x * W, y: p.y * H } : fallback);
let a = api.from ?? at(d.from, { x: 0, y: H / 2 });
let b = api.to ?? at(d.to, { x: W, y: H / 2 });
const len = Math.hypot(b.x - a.x, b.y - a.y) || 1;
const ux = (b.x - a.x) / len,
  uy = (b.y - a.y) / len;
const head = d.head ?? "filled";
const hl = Math.max(7, w * 4.2),
  hw = hl * 0.42;
const away = (p, q) => {
  const l = Math.hypot(p.x - q.x, p.y - q.y) || 1;
  return { x: (p.x - q.x) / l, y: (p.y - q.y) / l };
};
const tip = (p, dir) => {
  const back = { x: p.x - dir.x * hl, y: p.y - dir.y * hl };
  const side = { x: -dir.y * hw, y: dir.x * hw };
  if (head === "open")
    return `<path d="M${back.x + side.x} ${back.y + side.y}L${p.x} ${p.y}L${back.x - side.x} ${back.y - side.y}" fill="none" stroke="${color}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"/>`;
  const notch = { x: p.x - dir.x * hl * 0.78, y: p.y - dir.y * hl * 0.78 };
  return `<path d="M${p.x} ${p.y}L${back.x + side.x} ${back.y + side.y}L${notch.x} ${notch.y}L${back.x - side.x} ${back.y - side.y}Z" fill="${color}" stroke="${color}" stroke-width="${w * 0.5}" stroke-linejoin="round"/>`;
};
// The line stops inside a filled head instead of poking through its point.
const pull = head === "filled" ? hl * 0.7 : 0;
const back = (p, dir, by) => ({ x: p.x - dir.x * by, y: p.y - dir.y * by });
const route = d.route ?? "curve";
// end and start point out of the line at each end; mid and normal place the label.
let line, end, start, mid, normal;
if (route === "elbow" || route === "corner") {
  const dx = b.x - a.x,
    dy = b.y - a.y;
  // Each end runs along the side its anchor faces, else along the given or longer axis.
  const axis = (side) =>
    side === "left" || side === "right"
      ? "h"
      : side === "top" || side === "bottom"
        ? "v"
        : null;
  const other = (x) => (x === "h" ? "v" : "h");
  const given =
    d.first === "horizontal" ? "h" : d.first === "vertical" ? "v" : null;
  const leave =
    given ??
    axis(api.fromSide) ??
    axis(api.toSide) ??
    (Math.abs(dx) >= Math.abs(dy) ? "h" : "v");
  const arrive =
    route === "corner"
      ? other(leave)
      : given
        ? leave
        : (axis(api.toSide) ?? leave);
  const k = 0.5 + Number(d.bend ?? 0);
  // A line first runs this far straight out of the side it leaves, and into the side it
  // arrives at, before it turns, so it never turns on a module's edge or runs back
  // through the module.
  const STUB = 24;
  // The way out of a module through an end's side along an axis: 1, -1, or 0 when the
  // end is not on a side across that axis.
  const out = (side, ax) =>
    ax === "h"
      ? side === "right" ? 1 : side === "left" ? -1 : 0
      : side === "bottom" ? 1 : side === "top" ? -1 : 0;
  // Points given by their coordinate along an axis and across it.
  const at = (ax, along, across) =>
    ax === "h" ? { x: along, y: across } : { x: across, y: along };
  const ak = leave === "h" ? "x" : "y",
    ck = leave === "h" ? "y" : "x";
  const fo = out(api.fromSide, leave),
    to = out(api.toSide, arrive);
  let pts;
  if (leave !== arrive) {
    // One turn, where the line leaves along one axis and arrives along the other, as long
    // as it moves out of both modules; otherwise it steps out of each and goes round.
    const leaves = fo === 0 || fo * (b[ak] - a[ak]) >= STUB,
      arrives = to === 0 || to * (a[ck] - b[ck]) >= STUB;
    if (leaves && arrives) pts = [a, at(leave, b[ak], a[ck]), b];
    else {
      const s = at(leave, a[ak] + fo * STUB, a[ck]),
        e = at(leave, b[ak], b[ck] + to * STUB);
      pts = [a, s, at(leave, s[ak], e[ck]), e, b];
    }
  } else {
    // A cross segment between two runs along one axis: bend places it between the ends,
    // and it stays out of the modules the line leaves and arrives at.
    const want = a[ak] + (b[ak] - a[ak]) * k;
    let lo = -Infinity,
      hi = Infinity;
    if (fo > 0) lo = Math.max(lo, a[ak] + STUB);
    if (fo < 0) hi = Math.min(hi, a[ak] - STUB);
    if (to > 0) lo = Math.max(lo, b[ak] + STUB);
    if (to < 0) hi = Math.min(hi, b[ak] - STUB);
    const ahead =
      (fo === 0 || fo * (b[ak] - a[ak]) > 0) &&
      (to === 0 || to * (a[ak] - b[ak]) > 0);
    if (lo <= hi || ahead) {
      // Ends facing each other closer than two steps keep the cross segment between them.
      const c =
        lo <= hi
          ? Math.min(hi, Math.max(lo, want))
          : Math.min(Math.max(a[ak], b[ak]), Math.max(Math.min(a[ak], b[ak]), want));
      pts = [a, at(leave, c, a[ck]), at(leave, c, b[ck]), b];
    } else {
      // Back to back: out of each, across between them, and in.
      const m = a[ck] + (b[ck] - a[ck]) * k,
        c1 = a[ak] + fo * STUB,
        c2 = b[ak] + to * STUB;
